const fs = require('fs');
const de = JSON.parse(fs.readFileSync('de.json', 'utf8'));
const ka = JSON.parse(fs.readFileSync('ka.json', 'utf8'));

function getKeys(obj, prefix = '') {
  let keys = [];
  for (const key in obj) {
    if (typeof obj[key] === 'object' && obj[key] !== null && !Array.isArray(obj[key])) {
      keys = keys.concat(getKeys(obj[key], prefix + key + '.'));
    } else if (Array.isArray(obj[key])) {
      obj[key].forEach((item, index) => {
        if (typeof item === 'object' && item !== null) {
          keys = keys.concat(getKeys(item, prefix + key + '[' + index + '].'));
        } else {
          keys.push(prefix + key + '[' + index + ']');
        }
      });
    } else {
      keys.push(prefix + key);
    }
  }
  return keys;
}
const d = getKeys(de.trustx);
const k = getKeys(ka.trustx);
console.log('Missing in trustx:', d.filter(x => !k.includes(x)));
